   225      struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
   226      struct lwan_request_parser_helper *helper = request->helper;
   227      const unsigned int proto_signature_length = 16;
   228      unsigned int size;
   229      struct lwan_proxy *const proxy = request->proxy;
   230
   231      enum { LOCAL = 0x20, PROXY = 0x21, TCP4 = 0x11, TCP6 = 0x21 };
   232
   233      size = proto_signature_length + (unsigned int)ntohs(hdr->len);
   234      if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
   235          return NULL;
   236      if (UNLIKELY(size >= helper->buffer->len))
   237          return NULL;
   238
   239      if (LIKELY(hdr->cmd_ver == PROXY)) {
   240          if (hdr->fam == TCP4) {
   241              struct sockaddr_in *from = &proxy->from.ipv4;
   242              struct sockaddr_in *to = &proxy->to.ipv4;
   243
   244              to->sin_family = from->sin_family = AF_INET;
   245
   246              from->sin_addr.s_addr = hdr->addr.ip4.src_addr;
   247              from->sin_port = hdr->addr.ip4.src_port;
   248
   249              to->sin_addr.s_addr = hdr->addr.ip4.dst_addr;
   250              to->sin_port = hdr->addr.ip4.dst_port;
   251          } else if (hdr->fam == TCP6) {
   252              struct sockaddr_in6 *from = &proxy->from.ipv6;
   253              struct sockaddr_in6 *to = &proxy->to.ipv6;
   254
   255              from->sin6_family = to->sin6_family = AF_INET6;
   256
   257              from->sin6_addr = hdr->addr.ip6.src_addr;
   258              from->sin6_port = hdr->addr.ip6.src_port;
   259
   260              to->sin6_addr = hdr->addr.ip6.dst_addr;
   261              to->sin6_port = hdr->addr.ip6.dst_port;
   262          } else {
   263              return NULL;
   264          }
   265      } else if (hdr->cmd_ver == LOCAL) {
   266          struct sockaddr_in *from = &proxy->from.ipv4;
   267          struct sockaddr_in *to = &proxy->to.ipv4;
   268
   269          from->sin_family = to->sin_family = AF_UNSPEC;
   270      } else {
   271          return NULL;
   272      }
   273
   274      request->flags |= REQUEST_PROXIED;
   275      return buffer + size;
